export type OnSettingsGetEvent = {
    args: {
        name: string | false;
    };
    return: unknown | Record<string, unknown>;
};
export type OnSettingsSetEvent = {
    args: {
        name: string;
        value: unknown;
    };
    return: unknown;
};
export type OnSettingsUnsetEvent = {
    args: {
        name: string;
    };
    return: void;
};
export type GetSettingsEvent = {
    args: void;
    return: Record<string, unknown>;
};
export type SetSettingsEvent = {
    args: Record<string, unknown>;
    return: void;
};
export type HomeySettingsEvents = {
    'settings.get': OnSettingsGetEvent;
    'settings.set': OnSettingsSetEvent;
    'settings.unset': OnSettingsUnsetEvent;
};
export type SDKSettingsEvents = {
    getSettings: GetSettingsEvent;
    setSettings: SetSettingsEvent;
};
